-- Every verdict must read 'ok'. LOAD DATA LOCAL turns CHECK and key
-- failures into warnings and skips the row, so compare each table's
-- loaded row count with the number of rows staged.
SELECT 'ExtractBatch' AS table_name, COUNT(*) AS rows_loaded, 1 AS rows_staged, IF(COUNT(*) = 1, 'ok', 'ROWS LOST') AS verdict FROM ExtractBatch
UNION ALL SELECT 'Neighborhood' AS table_name, COUNT(*) AS rows_loaded, 41 AS rows_staged, IF(COUNT(*) = 41, 'ok', 'ROWS LOST') AS verdict FROM Neighborhood
UNION ALL SELECT 'LocationPoint' AS table_name, COUNT(*) AS rows_loaded, 13448 AS rows_staged, IF(COUNT(*) = 13448, 'ok', 'ROWS LOST') AS verdict FROM LocationPoint
UNION ALL SELECT 'AssessorBlock' AS table_name, COUNT(*) AS rows_loaded, 4288 AS rows_staged, IF(COUNT(*) = 4288, 'ok', 'ROWS LOST') AS verdict FROM AssessorBlock
UNION ALL SELECT 'BlockAddress' AS table_name, COUNT(*) AS rows_loaded, 7677 AS rows_staged, IF(COUNT(*) = 7677, 'ok', 'ROWS LOST') AS verdict FROM BlockAddress
UNION ALL SELECT 'BedroomLabel' AS table_name, COUNT(*) AS rows_loaded, 45 AS rows_staged, IF(COUNT(*) = 45, 'ok', 'ROWS LOST') AS verdict FROM BedroomLabel
UNION ALL SELECT 'BathroomLabel' AS table_name, COUNT(*) AS rows_loaded, 31 AS rows_staged, IF(COUNT(*) = 31, 'ok', 'ROWS LOST') AS verdict FROM BathroomLabel
UNION ALL SELECT 'SquareFootageBand' AS table_name, COUNT(*) AS rows_loaded, 19 AS rows_staged, IF(COUNT(*) = 19, 'ok', 'ROWS LOST') AS verdict FROM SquareFootageBand
UNION ALL SELECT 'RentBand' AS table_name, COUNT(*) AS rows_loaded, 33 AS rows_staged, IF(COUNT(*) = 33, 'ok', 'ROWS LOST') AS verdict FROM RentBand
UNION ALL SELECT 'UnitReport' AS table_name, COUNT(*) AS rows_loaded, 551551 AS rows_staged, IF(COUNT(*) = 551551, 'ok', 'ROWS LOST') AS verdict FROM UnitReport
UNION ALL SELECT 'ReportUtility' AS table_name, COUNT(*) AS rows_loaded, 701950 AS rows_staged, IF(COUNT(*) = 701950, 'ok', 'ROWS LOST') AS verdict FROM ReportUtility
UNION ALL SELECT 'OccupancyHistory' AS table_name, COUNT(*) AS rows_loaded, 81085 AS rows_staged, IF(COUNT(*) = 81085, 'ok', 'ROWS LOST') AS verdict FROM OccupancyHistory;

-- Every orphan count must be 0.
SELECT 'UnitReport -> LocationPoint' AS reference, COUNT(*) AS orphans FROM UnitReport r LEFT JOIN LocationPoint p ON p.point_id = r.point_id WHERE r.point_id IS NOT NULL AND p.point_id IS NULL
UNION ALL
SELECT 'UnitReport -> BlockAddress' AS reference, COUNT(*) AS orphans FROM UnitReport r LEFT JOIN BlockAddress b ON b.block_address_id = r.block_address_id WHERE r.block_address_id IS NOT NULL AND b.block_address_id IS NULL
UNION ALL
SELECT 'UnitReport -> AssessorBlock' AS reference, COUNT(*) AS orphans FROM UnitReport r LEFT JOIN AssessorBlock b ON b.block_num = r.block_num WHERE r.block_num IS NOT NULL AND b.block_num IS NULL
UNION ALL
SELECT 'ReportUtility -> UnitReport' AS reference, COUNT(*) AS orphans FROM ReportUtility c LEFT JOIN UnitReport r ON r.unique_id = c.unique_id WHERE r.unique_id IS NULL
UNION ALL
SELECT 'OccupancyHistory -> UnitReport' AS reference, COUNT(*) AS orphans FROM OccupancyHistory c LEFT JOIN UnitReport r ON r.unique_id = c.unique_id WHERE r.unique_id IS NULL;
